import { create } from 'zustand';
import { devtools, persist, subscribeWithSelector } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';

interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

interface CartStore {
  items: CartItem[];
  coupon: string | null;
  // Actions colocated with state
  addItem: (product: Omit<CartItem, 'quantity'>) => void;
  removeItem: (id: string) => void;
  updateQuantity: (id: string, quantity: number) => void;
  applyCoupon: (code: string) => void;
  clearCart: () => void;
  // Computed (getter-style)
  getTotal: () => number;
  getItemCount: () => number;
}

export const useCartStore = create<CartStore>()(
  devtools(
    persist(
      immer((set, get) => ({
        items: [],
        coupon: null,

        addItem: (product) =>
          set((state) => {
            const existing = state.items.find((i) => i.id === product.id);
            if (existing) {
              existing.quantity += 1;
            } else {
              state.items.push({ ...product, quantity: 1 });
            }
          }),

        removeItem: (id) =>
          set((state) => {
            state.items = state.items.filter((i) => i.id !== id);
          }),

        updateQuantity: (id, quantity) =>
          set((state) => {
            const item = state.items.find((i) => i.id === id);
            if (item) {
              if (quantity <= 0) {
                state.items = state.items.filter((i) => i.id !== id);
              } else {
                item.quantity = quantity;
              }
            }
          }),

        applyCoupon: (code) => set({ coupon: code }),

        clearCart: () => set({ items: [], coupon: null }),

        getTotal: () => {
          const { items } = get();
          return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
        },

        getItemCount: () => {
          const { items } = get();
          return items.reduce((sum, item) => sum + item.quantity, 0);
        },
      })),
      {
        name: 'cart-storage',
        partialize: (state) => ({ items: state.items, coupon: state.coupon }),
      }
    ),
    { name: 'CartStore' }
  )
);

// Usage in components — subscribe to specific slices
function CartBadge() {
  const itemCount = useCartStore((state) => state.getItemCount());
  return <span className="badge">{itemCount}</span>;
}

function CartTotal() {
  const total = useCartStore((state) => state.getTotal());
  const coupon = useCartStore((state) => state.coupon);
  return (
    <div>
      <span>${total.toFixed(2)}</span>
      {coupon && <span className="coupon">Coupon: {coupon}</span>}
    </div>
  );
}

function AddToCartButton({ product }: { product: Product }) {
  // Only subscribes to addItem — won't re-render when items change
  const addItem = useCartStore((state) => state.addItem);
  return <button onClick={() => addItem(product)}>Add to Cart</button>;
}

import { create } from 'zustand';
import { StateCreator } from 'zustand';

// Slice pattern for large stores
interface AuthSlice {
  user: User | null;
  token: string | null;
  isLoading: boolean;
  login: (credentials: Credentials) => Promise<void>;
  logout: () => void;
  refreshToken: () => Promise<void>;
}

interface NotificationSlice {
  notifications: Notification[];
  unreadCount: number;
  addNotification: (notification: Notification) => void;
  markAsRead: (id: string) => void;
  clearAll: () => void;
}

// Each slice is defined independently
const createAuthSlice: StateCreator<
  AuthSlice & NotificationSlice,
  [['zustand/immer', never]],
  [],
  AuthSlice
> = (set, get) => ({
  user: null,
  token: null,
  isLoading: false,

  login: async (credentials) => {
    set({ isLoading: true });
    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(credentials),
      });

      if (!response.ok) throw new Error('Login failed');

      const { user, token } = await response.json();
      set({ user, token, isLoading: false });

      // Cross-slice communication
      get().addNotification({
        id: crypto.randomUUID(),
        message: `Welcome back, ${user.name}!`,
        type: 'success',
        read: false,
        createdAt: new Date().toISOString(),
      });
    } catch (error) {
      set({ isLoading: false });
      throw error;
    }
  },

  logout: () => {
    set({ user: null, token: null });
  },

  refreshToken: async () => {
    const { token } = get();
    if (!token) return;

    const response = await fetch('/api/auth/refresh', {
      headers: { Authorization: `Bearer ${token}` },
    });

    if (response.ok) {
      const { token: newToken } = await response.json();
      set({ token: newToken });
    } else {
      get().logout();
    }
  },
});

const createNotificationSlice: StateCreator<
  AuthSlice & NotificationSlice,
  [['zustand/immer', never]],
  [],
  NotificationSlice
> = (set) => ({
  notifications: [],
  unreadCount: 0,

  addNotification: (notification) =>
    set((state) => {
      state.notifications.unshift(notification);
      state.unreadCount += 1;
    }),

  markAsRead: (id) =>
    set((state) => {
      const notification = state.notifications.find((n) => n.id === id);
      if (notification && !notification.read) {
        notification.read = true;
        state.unreadCount -= 1;
      }
    }),

  clearAll: () => set({ notifications: [], unreadCount: 0 }),
});

// Combine slices
export const useAppStore = create<AuthSlice & NotificationSlice>()(
  immer((...args) => ({
    ...createAuthSlice(...args),
    ...createNotificationSlice(...args),
  }))
);

import { atom, useAtom, useAtomValue, useSetAtom } from 'jotai';
import { atomWithStorage, atomWithQuery } from 'jotai/utils';
import { focusAtom } from 'jotai-optics';

